layers.vertex:
attribute vec3 aO; attribute float aYaw, aT; uniform float uTime; varying float vS, vY, vU;
    void main(){
      float u = uTime - aT - 0.10; if (u < 0. || u > .7){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 dir = vec3(-sin(aYaw), 0., -cos(aYaw));             // forward = -z at yaw 0
      float s = position.x*.5 + .5, W = .26;
      vec3 P = aO + vec3(0., 1.12, 0.) + dir*(.25 + s*3.30);
      vec3 side = normalize(cross(dir, P - cameraPosition));
      vS = s; vY = position.y*W; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*W, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float s = vS;
      float prof = sin(3.14159*pow(s, 1.35));                 // thin at the origin, fullest near the front, sharp tip
      float front = pow(prof, 3.)*smoothstep(.3, .8, s);       // the part that matters: the piercing front
      float grow = 1. - pow(1. - clamp(vU/0.08, 0., 1.), 2.);
      float wipe = max(vU - .2, 0.)/.35;                       // after the hold, fades from the Fighter outward; tip last
      float alive = smoothstep(grow + .02, grow - .03, s) * smoothstep(wipe - .08 - .35*front, wipe + .2 - .35*front, s);
      float fade = 1. - smoothstep(.52, .7, vU);
      float thin = 1. - .4*smoothstep(.15, .6, vU)*(1. - .5*front);
      float ends = pow(prof, .75);
      float w = (.003 + .027*pow(prof, 1.3) + .028*front)*thin;
      float d = abs(vY);
      float band = exp(-pow(d/w, 2.4)), core = lcore(d, w*.35);
      float head = exp(-pow((s - grow)/.03, 2.)) * (1. - step(1., grow));
      float k = alive*fade*ends*(vU > 0.08 && vU < 0.113 ? 1.25 : 1.);
      vec3 col = mix(uOrange, uGold, .35 + .65*prof);
      vec3 outc = (col*band*(.44 + .24*prof) + mix(uGold, vec3(1., .96, .88), .6)*(core*.28*prof + head*band*.4))*k;
      outc *= 1. - smoothstep(.22, .255, abs(vY));
      gl_FragColor = vec4(outc, 1.);
    }
